us:13px;padding:25px 15px;text-align:center;background:#f5faf6;color:#315341;cursor:pointer}.drop-zone.is-over{background:#e7f5eb;border-color:#176b50}.drop-zone input{display:none}.media-help{font-size:12px;color:#748178;margin:8px 0 0}.media-status{font-size:12px;color:#176b50;font-weight:700}@media(max-width:650px){.panel{grid-template-columns:1fr}.wide{grid-column:auto}}
