</style></head><body><main class="wrap"><h1><?= $editing?'Konaklamayı düzenle':'Yeni konaklama ekle' ?></h1><p class="hint">İlan bilgileri kaydedildiğinde web sitesinde yayınlanabilir.</p><form method="post" enctype="multipart/form-data" action="<?= e($formAction ?? '/admin/properties/save') ?>"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)($property['id']??0) ?>"><div class="panel">
