<label>Ülke<select name="location_country_id" id="locationCountry" required><option value="">Ülke seçin</option><?php foreach($countryOptions as $v): ?><option value="<?= (int)$v['id'] ?>" <?= $selectedCountry===(int)$v['id']?'selected':'' ?>><?= e($v['name']) ?></option><?php endforeach; ?></select></label>
<label>Şehir<select name="location_city_id" id="locationCity" required><option value="">Şehir seçin</option><?php foreach($cityOptions as $v): ?><option value="<?= (int)$v['id'] ?>" <?= $selectedCity===(int)$v['id']?'selected':'' ?>><?= e($v['name']) ?></option><?php endforeach; ?></select></label>
<label>İlçe<select name="location_district_id" id="locationDistrict"><option value="">İlçe seçin (isteğe bağlı)</option><?php foreach($districtOptions as $v): ?><option value="<?= (int)$v['id'] ?>" <?= $selectedDistrict===(int)$v['id']?'selected':'' ?>><?= e($v['name']) ?></option><?php endforeach; ?></select></label>
