<section class="wide media-manager" id="mediaManager" data-property-id="<?= (int)($property['id']??0) ?>" data-manage-url="<?= e(($deleteMediaAction ?? '/admin/properties/media/delete')==='/vendor/properties/media/delete'?'/vendor/properties/media/manage':'/admin/properties/media/manage') ?>" data-delete-url="<?= e($deleteMediaAction ?? '/admin/properties/media/delete') ?>">
<div class="media-toolbar"><div><strong>Konaklama fotoğraf galerisi</strong><div class="media-help">Fotoğrafları sürükleyerek sıralayın. Kapak fotoğrafını seçin.</div></div><span class="media-status" id="mediaStatus"><?= count($existingImages??[]) ?> fotoğraf</span></div>
<div class="media-grid" id="existingMediaGrid"><?php foreach(($existingImages??[]) as $image): ?><article class="media-card" draggable="true" data-media-id="<?= (int)$image['id'] ?>"><img src="<?= e(preg_match('~^https?://~i',(string)$image['file_path'])?$image['file_path']:'/'.ltrim($image['file_path'],'/')) ?>" alt="<?= e($image['alt_text']??'') ?>"><span class="cover-tag" <?= (int)$image['is_cover']?'':'hidden' ?>>KAPAK FOTOĞRAFI</span><div class="media-actions"><button type="button" data-set-cover="<?= (int)$image['id'] ?>">Kapak yap</button><button type="button" class="danger" data-delete-media="<?= (int)$image['id'] ?>">Sil</button></div></article><?php endforeach; ?></div>
<label class="drop-zone" id="mediaDropZone"><input type="file" id="propertyImages" name="images[]" accept="image/jpeg,image/png,image/webp" multiple><strong>＋ Fotoğrafları buraya sürükleyin veya seçmek için dokunun</strong><div class="media-help">JPG, PNG veya WebP · en fazla 30 fotoğraf · her biri 12 MB</div></label>
<div class="media-grid" id="newMediaPreview"></div><p class="media-help">Yeni fotoğrafları da sürükleyerek sıralayabilirsiniz. Önizlemeler kaydettiğiniz sırayla yüklenir.</p>
</section><div class="wide"><button class="btn" type="submit">Kaydet</button> <a href="<?= e($backUrl ?? '/admin/properties') ?>">Vazgeç</a></div></div></form></main><script>
(function(){
var manager=document.getElementById('mediaManager');if(!manager)return;
var form=manager.closest('form'),input=document.getElementById('propertyImages'),drop=document.getElementById('mediaDropZone'),preview=document.getElementById('newMediaPreview'),grid=document.getElementById('existingMediaGrid'),status=document.getElementById('mediaStatus');
var manageUrl=manager.dataset.manageUrl,deleteUrl=manager.dataset.deleteUrl,propertyId=manager.dataset.propertyId,csrf=(form.querySelector('[name="_csrf"]')||{}).value||'';
function flash(message){status.textContent=message}
function post(data){data.set('_csrf',csrf);data.set('property_id',propertyId);return fetch(manageUrl,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','X-Requested-With':'XMLHttpRequest'},body:new URLSearchParams(data)}).then(function(r){if(!r.ok)throw new Error('İşlem kaydedilemedi');return r.json()})}
function orderExisting(){var ids=Array.from(grid.querySelectorAll('[data-media-id]')).map(function(card){return card.dataset.mediaId});var data=new URLSearchParams();data.set('action','sort');ids.forEach(function(id){data.append('media_ids[]',id)});post(data).then(function(){flash(ids.length+' fotoğraf · Sıralama kaydedildi')}).catch(function(e){flash(e.message)})}
var dragging=null;
grid.addEventListener('dragstart',function(e){var card=e.target.closest('.media-card');if(!card)return;dragging=card;card.classList.add('dragging');e.dataTransfer.effectAllowed='move'});
grid.addEventListener('dragend',function(){if(dragging)dragging.classList.remove('dragging');dragging=null;orderExisting()});
grid.addEventListener('dragover',function(e){e.preventDefault();var target=e.target.closest('.media-card');if(!target||!dragging||target===dragging)return;var rect=target.getBoundingClientRect();grid.insertBefore(dragging,e.clientY<rect.top+rect.height/2?target:target.nextSibling)});
grid.addEventListener('click',function(e){var cover=e.target.closest('[data-set-cover]'),del=e.target.closest('[data-delete-media]');if(cover){var data=new URLSearchParams({action:'cover',media_id:cover.dataset.setCover});post(data).then(function(){grid.querySelectorAll('.cover-tag').forEach(function(x){x.hidden=true});cover.closest('.media-card').querySelector('.cover-tag').hidden=false;flash('Kapak fotoğrafı güncellendi')}).catch(function(x){flash(x.message)})}
if(del){if(!confirm('Bu fotoğrafı silmek istediğinize emin misiniz?'))return;var f=new FormData();f.append('_csrf',csrf);f.append('property_id',propertyId);f.append('media_id',del.dataset.deleteMedia);fetch(deleteUrl,{method:'POST',body:f}).then(function(r){if(!r.ok)throw new Error('Fotoğraf silinemedi');del.closest('.media-card').remove();flash('Fotoğraf silindi')}).catch(function(x){flash(x.message)})}});
var files=[];
function setFiles(list){files=Array.from(list).slice(0,30);var transfer=new DataTransfer();files.forEach(function(f){transfer.items.add(f)});input.files=transfer.files;renderPreview()}
function renderPreview(){preview.innerHTML='';files.forEach(function(file,index){var card=document.createElement('article');card.className='media-card';card.draggable=true;card.dataset.index=index;var img=document.createElement('img');img.alt=file.name;img.src=URL.createObjectURL(file);var label=document.createElement('div');label.className='media-help';label.textContent=file.name;card.append(img,label);preview.append(card)});
preview.querySelectorAll('.media-card').forEach(function(card){card.addEventListener('dragstart',function(e){card.classList.add('dragging');e.dataTransfer.setData('text/plain',card.dataset.index)});card.addEventListener('dragend',function(){card.classList.remove('dragging')})});
}
preview.addEventListener('dragover',function(e){e.preventDefault()});preview.addEventListener('drop',function(e){e.preventDefault();var from=Number(e.dataTransfer.getData('text/plain'));var target=e.target.closest('.media-card');if(!target||!Number.isInteger(from))return;var to=Number(target.dataset.index);var moved=files.splice(from,1)[0];files.splice(to,0,moved);setFiles(files)});
input.addEventListener('change',function(){setFiles(input.files);flash(files.length+' yeni fotoğraf seçildi')});
['dragenter','dragover'].forEach(function(name){drop.addEventListener(name,function(e){e.preventDefault();drop.classList.add('is-over')})});['dragleave','drop'].forEach(function(name){drop.addEventListener(name,function(){drop.classList.remove('is-over')})});drop.addEventListener('drop',function(e){e.preventDefault();setFiles(e.dataTransfer.files)});
form.addEventListener('submit',function(e){if(files.length>30){e.preventDefault();flash('En fazla 30 fotoğraf yükleyebilirsiniz.')}});
})();
(function(){var fields=[document.getElementById('locationCountry'),document.getElementById('locationCity'),document.getElementById('locationDistrict'),document.getElementById('locationNeighborhood')];if(fields.some(function(x){return !x}))return;
var labels=['Ülke seçin','Şehir seçin','İlçe seçin (isteğe bağlı)','Semt / mahalle seçin (isteğe bağlı)'];
function resetFrom(index){for(var i=index;i<fields.length;i++){fields[i].innerHTML='<option value="">'+labels[i]+'</option>';fields[i].disabled=i>1}}
async function load(index,parent){resetFrom(index);if(!parent)return;var response=await fetch('<?= e(app_url('/locations/children')) ?>?parent_id='+encodeURIComponent(parent),{headers:{'Accept':'application/json'}});if(!response.ok)return;var rows=await response.json();rows.forEach(function(row){var option=document.createElement('option');option.value=row.id;option.textContent=row.name;fields[index].appendChild(option)});fields[index].disabled=false}
fields[0].addEventListener('change',function(){load(1,this.value)});
fields[1].addEventListener('change',function(){load(2,this.value)});
fields[2].addEventListener('change',function(){load(3,this.value)});
fields[1].disabled=!fields[0].value;fields[2].disabled=!fields[1].value;fields[3].disabled=!fields[2].value;
})();
</script></body></html>